                            aria-expanded={!collapsed}
                          >
                            <span class="inline-block w-3">
                              {collapsed ? "▸" : "▾"}
                            </span>
                            {memo.personaName}
                          </button>
                          <div class="flex items-center gap-2">
                            <SpeakButton
                              compact
                              id={`analysis-memo-${memo.personaId}`}
                              text={memo.text}
                              voice={
                                store.personas.find(
                                  (p) => p.id === memo.personaId,
                                )?.speechVoice
                              }
                              voices={
                                store.personas.find(
                                  (p) => p.id === memo.personaId,
                                )?.speechVoices
                              }
                              instructions={
                                store.personas.find(
                                  (p) => p.id === memo.personaId,
                                )?.voice
                              }
                              label={memo.personaName}
                            />
                            <button
                              onClick$={() =>
                                copyAnalysisText(memo.personaId, memo.text)
