                </>
              ) : (
                <>
                  <InstrumentArt kind="research" size="compact" />
                  <TaskDesk
                    key={props.folioId}
                    folioId={props.folioId}
                    selectedText={state.text}
                  />
                </>
              )}
            </InstrumentMotion>
          </>
        )}
      </div>
    </dialog>
  );
