                  data-scene-dimension={id}
                >
                  <dt>{label}</dt>
                  <dd>
                    {spans.map((span) => (
                      <div class="scene-bench__evidence" key={span.id}>
                        <blockquote>{span.text}</blockquote>
                        <div class="scene-bench__evidence-foot">
                          <span>
                            {selected
                              ? `${assessment!.model} selection`
                              : `Local cue: “${local.find((cue) => cue.spanId === span.id)?.cue ?? ""}”`}
                          </span>
                          {props.onLocate$ && (
                            <button
                              type="button"
                              onClick$={async () => {
                                if (sceneSpanMatches(span, props.passage))
                                  await props.onLocate$?.(span, props.passage);
                              }}
                            >
                              Find in passage
                    <p role="status">{capabilities.error}</p>
                    <EntityInstrument
                      index={entities.value}
                      contextKey={`${props.folioId}:${entities.value.key}`}
                      onJump$={async (span, indexKey) => {
                        if (await props.onEntityJump$?.(span, indexKey))
                          dialog.value?.close("manuscript");
                        else
