  onRead$?: QRL<(passage: ScenePassage) => Promise<void>>;
}

function canRequest(capability: SceneProviderCapability | undefined): boolean {
  return (
    !!capability?.available &&
    !!capability.destination.trim() &&
    !!capability.costLabel.trim()
  );
}

